'use strict';

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function checkDelimiter(options) {
  const d = options.delimiter === undefined ? ',' : options.delimiter;
  if (typeof d !== 'string' || d.length !== 1 || d === '"' || d === '\r' || d === '\n') {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
  return d;
}

function checkOptions(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be an object');
  }
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  checkOptions(options);
  const delimiter = checkDelimiter(options);
  const useHeader = options.header === true;
  const skipEmpty = options.skipEmptyLines === true;

  let i = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  const n = text.length;
  let line = 1;
  let lineStart = i;
  const records = [];
  let header = null;

  // Consumes one line break at i (CRLF counts as one) and updates position.
  const breakLine = () => {
    i += text[i] === '\r' && text[i + 1] === '\n' ? 2 : 1;
    line++;
    lineStart = i;
  };
  const isBreak = (c) => c === '\r' || c === '\n';

  while (i < n) {
    const recordLine = line;
    const fields = [];
    const starts = [];
    const emptyLine = isBreak(text[i]);
    let ended = false;

    while (!ended) {
      starts.push({ line, column: i - lineStart + 1 });
      if (text[i] === '"') {
        const open = { line, column: i - lineStart + 1 };
        let value = '';
        let j = i + 1;
        let closed = false;
        i = j;
        while (j < n) {
          const c = text[j];
          if (c === '"') {
            if (text[j + 1] === '"') {
              value += text.slice(i, j + 1);
              j += 2;
              i = j;
              continue;
            }
            value += text.slice(i, j);
            closed = true;
            break;
          }
          if (isBreak(c)) {
            value += text.slice(i, j);
            i = j;
            const crlf = c === '\r' && text[j + 1] === '\n';
            value += crlf ? '\r\n' : c;
            breakLine();
            j = i;
            continue;
          }
          j++;
        }
        if (!closed) throw new CsvError('Unterminated quoted field', open.line, open.column);
        i = j + 1;
        fields.push(value);
        if (i < n && text[i] !== delimiter && !isBreak(text[i])) {
          throw new CsvError('Unexpected character after closing quote', line, i - lineStart + 1);
        }
      } else {
        let j = i;
        while (j < n && text[j] !== delimiter && !isBreak(text[j])) j++;
        fields.push(text.slice(i, j));
        i = j;
      }

      if (i >= n) {
        ended = true;
      } else if (text[i] === delimiter) {
        i++;
        // A trailing delimiter at end of input still starts an empty field.
        if (i >= n) {
          starts.push({ line, column: i - lineStart + 1 });
          fields.push('');
          ended = true;
        }
      } else {
        breakLine();
        ended = true;
      }
    }

    if (emptyLine && skipEmpty) continue;

    if (!useHeader) {
      records.push(fields);
    } else if (header === null) {
      const seen = new Set();
      fields.forEach((name, k) => {
        if (seen.has(name)) {
          throw new CsvError(`Duplicate header name "${name}"`, starts[k].line, starts[k].column);
        }
        seen.add(name);
      });
      header = fields;
    } else {
      if (fields.length !== header.length) {
        throw new CsvError(
          `Expected ${header.length} fields but found ${fields.length}`,
          recordLine,
          1
        );
      }
      const obj = {};
      header.forEach((name, k) => {
        Object.defineProperty(obj, name, {
          value: fields[k], writable: true, enumerable: true, configurable: true,
        });
      });
      records.push(obj);
    }
  }
  return records;
}

function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  checkOptions(options);
  const delimiter = checkDelimiter(options);
  const eol = options.eol === undefined ? '\r\n' : options.eol;
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError("eol must be '\\r\\n' or '\\n'");
  const header = options.header;
  if (header !== undefined && !Array.isArray(header)) {
    throw new TypeError('header must be an array of column names');
  }

  const text = (v) => {
    if (typeof v === 'string') return v;
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    if (v === null || v === undefined) return '';
    throw new TypeError(`Unsupported value type: ${typeof v}`);
  };
  const quote = (s) => {
    const needs =
      s.includes(delimiter) || s.includes('"') || s.includes('\r') || s.includes('\n') ||
      s.startsWith(' ') || s.endsWith(' ');
    return needs ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const line = (values) => {
    if (values.length === 1 && values[0] === '') return '""';
    return values.map((v) => quote(text(v))).join(delimiter);
  };

  const out = [];
  if (header !== undefined) out.push(line(header));
  for (const row of rows) {
    if (Array.isArray(row)) {
      out.push(line(row));
    } else if (header !== undefined && row !== null && typeof row === 'object') {
      out.push(line(header.map((k) => (Object.prototype.hasOwnProperty.call(row, k) ? row[k] : ''))));
    } else {
      throw new TypeError('each record must be an array (or an object when header is set)');
    }
  }
  return out.map((l) => l + eol).join('');
}

module.exports = { parse, stringify, CsvError };

