const { parse, stringify, CsvError } = require('../src/csv.js');

const errAt = (fn, line, column) =>
  assert.throws(fn, (e) => e instanceof CsvError && e instanceof Error && e.line === line && e.column === column);

test('parse basics', () => {
  assert.deepEqual(parse(''), []);
  assert.deepEqual(parse('a,b\r\nc,d\ne,f\rg,h'), [['a', 'b'], ['c', 'd'], ['e', 'f'], ['g', 'h']]);
  assert.deepEqual(parse('﻿a,b\n'), [['a', 'b']]);
  assert.deepEqual(parse(' a , b '), [[' a ', ' b ']]);
  assert.deepEqual(parse('a,\n,'), [['a', ''], ['', '']]);
  assert.deepEqual(parse('a;b', { delimiter: ';' }), [['a', 'b']]);
  assert.deepEqual(parse('a"b,c'), [['a"b', 'c']]);
});

test('parse type and option validation', () => {
  for (const bad of [null, undefined, 1, {}, []]) assert.throws(() => parse(bad), TypeError);
  for (const d of ['', ',,', '"', '\r', '\n', 1]) assert.throws(() => parse('a', { delimiter: d }), TypeError);
});

test('parse quoted fields', () => {
  assert.deepEqual(parse('"a,b","c""d","e\r\nf\ng"'), [['a,b', 'c"d', 'e\r\nf\ng']]);
  assert.deepEqual(parse('"",x'), [['', 'x']]);
  assert.deepEqual(parse('"a"\n"b"'), [['a'], ['b']]);
});

test('empty lines and trailing break', () => {
  assert.deepEqual(parse('\n'), [['']]);
  assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
  assert.deepEqual(parse('a\n\nb\n'), [['a'], [''], ['b']]);
  assert.deepEqual(parse('a\n\nb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
  assert.deepEqual(parse('\n', { skipEmptyLines: true }), []);
  assert.deepEqual(parse('""\n', { skipEmptyLines: true }), [['']]);
});

test('parse errors carry positions', () => {
  errAt(() => parse('a,b\nc,"oops\nmore'), 2, 3);
  errAt(() => parse('a\n"x"y'), 2, 4);
  errAt(() => parse('"a\nb"x'), 2, 3);
  errAt(() => parse('a,b,a', { header: true }), 1, 5);
  errAt(() => parse('a,b\n1,2\n3', { header: true }), 3, 1);
  errAt(() => parse('a\n1,2', { header: true }), 2, 1);
  errAt(() => parse('\r\n\r\nb,b', { header: true, skipEmptyLines: true }), 3, 3);
});

test('header mode', () => {
  assert.deepEqual(parse('a,b\n1,2\n3,4', { header: true }), [{ a: '1', b: '2' }, { a: '3', b: '4' }]);
  assert.deepEqual(parse('a,b\n', { header: true }), []);
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('__proto__\nx', { header: true })[0].__proto__, 'x');
});

test('stringify basics', () => {
  assert.equal(stringify([]), '');
  assert.equal(stringify([['a', 1, true, null, undefined]]), 'a,1,true,,\r\n');
  assert.equal(stringify([['a,b', 'c"d', 'e\nf', ' x', 'y ', 'p\rq']], { eol: '\n' }),
    '"a,b","c""d","e\nf"," x","y ","p\rq"\n');
  assert.equal(stringify([['']]), '""\r\n');
  assert.equal(stringify([['a', 'b;c']], { delimiter: ';' }), 'a;"b;c"\r\n');
});

test('stringify header objects', () => {
  assert.equal(stringify([{ a: 1, b: 2 }, { b: 3 }, ['x', 'y']], { header: ['a', 'b'], eol: '\n' }),
    'a,b\n1,2\n,3\nx,y\n');
  assert.equal(stringify([], { header: ['a'] }), 'a\r\n');
});

test('stringify errors', () => {
  assert.throws(() => stringify('x'), TypeError);
  assert.throws(() => stringify([['a']], { eol: '\r' }), TypeError);
  assert.throws(() => stringify([['a']], { delimiter: '"' }), TypeError);
  assert.throws(() => stringify([[{}]]), TypeError);
  assert.throws(() => stringify([[Symbol('s')]]), TypeError);
  assert.throws(() => stringify([{ a: 1 }]), TypeError);
  assert.throws(() => stringify(['abc']), TypeError);
  assert.throws(() => stringify([], { header: 'a' }), TypeError);
});

test('round trip', () => {
  const rows = [[''], ['a'], [' '], ['', ''], ['"'], ['a,b', 'c\r\nd'], ['é😀', ' x '], ['\n'], ['', 'x']];
  for (const opts of [{}, { skipEmptyLines: true }, { delimiter: '\t', eol: '\n' }, { delimiter: ';', skipEmptyLines: true }]) {
    assert.deepEqual(parse(stringify(rows, opts), opts), rows);
    for (const r of rows) assert.deepEqual(parse(stringify([r], opts), opts), [r]);
  }
});

test('parse trim option', () => {
  assert.deepEqual(parse(' a \t, b ,\t'), [[' a \t', ' b ', '\t']]);
  assert.deepEqual(parse(' a \t, b ,\t', { trim: true }), [['a', 'b', '']]);
  assert.deepEqual(parse(' "  a ""x"" " \t,b', { trim: true }), [['  a "x" ', 'b']]);
  assert.deepEqual(parse('  "a"  \n\t"b"', { trim: true }), [['a'], ['b']]);
  assert.throws(() => parse('"a" x', { trim: true }), CsvError);
  assert.throws(() => parse(' "a"', {}), CsvError === undefined ? Error : undefined);
});

test('parse comment option', () => {
  const o = { comment: '#' };
  assert.deepEqual(parse('#c\na,#b\n#d\r\n\n#e', o), [['a', '#b'], ['']]);
  assert.deepEqual(parse('#c\na', { comment: '#', skipEmptyLines: true }), [['a']]);
  assert.deepEqual(parse('#a,b'), [['#a', 'b']]);
  assert.deepEqual(parse('"x\n#y"', o), [['x\n#y']]);
  assert.deepEqual(parse('#c\n#d\na,b', { comment: '#', header: true }), []);
  errAt(() => parse('#c\n#d\n"a', o), 3, 1);
  for (const c of ['', '##', ',', '"', '\r', '\n', 1, null]) {
    assert.throws(() => parse('a', { comment: c }), TypeError);
  }
  assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
});
